package com.bank.source;

import java.util.*;
import java.util.logging.*;

public class SourceDemo {
    private static final Logger log = Logger.getLogger("Source");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        int[] amounts = {100, 200, 300};
        List<Integer> list = List.of(100, 200, 300);
        SourceService service = new SourceService();

        log.info(() -> "Collection.stream sum : " + service.sumCollection(list));
        log.info(() -> "Arrays.stream sum     : " + service.sumArray(amounts));
        // Stream.of(primitiveArray) → 1-element stream of the WHOLE array (gotcha)
        log.warning(() -> "Stream.of(int[]) count: "
            + java.util.stream.Stream.of(amounts).count() + " (=1, the array itself!)");
    }
}

// ─── Would be in service/SourceService.java ───
class SourceService {
    long sumCollection(List<Integer> list) {
        return list.stream().mapToLong(Integer::longValue).sum();   // SIZED, splits well
    }
    long sumArray(int[] arr) {
        return java.util.Arrays.stream(arr).sum();                   // correct array streaming
    }
}
